update sku_stock
set stock = #{stock},
    lock_stock = #{lockStock}
where sku_id = #{skuId}

update sku_stock
set stock = stock - #{count},
    lock_stock = lock_stock + #{count}
where sku_id = #{skuId}
  and stock >= #{count}

update sku_stock
set stock = stock + #{count},
    lock_stock = lock_stock - #{count}
where sku_id = #{skuId}
  and lock_stock >= #{count}

update sku_stock
set lock_stock = lock_stock - #{count}
where sku_id = #{skuId}
  and lock_stock >= #{count}
